import * as T from'three';
export function createMarketProducts(M,baked){
 const sphere=new T.SphereGeometry(1,16,12),cube=new T.BoxGeometry(1,1,1),rod=new T.CylinderGeometry(1,1,1,16),cone=new T.ConeGeometry(1,1,12);for(const g of[sphere,cube,rod,cone])g.userData.shared=true;
 const cache=new Map(),mat=(color,roughness=.75)=>{const key=color+roughness;if(!cache.has(key))cache.set(key,new T.MeshStandardMaterial({color,roughness}));return cache.get(key)};
 const cream=mat('#f3e9d4'),white=mat('#f4ede0',.4),brown=mat('#785337'),red=mat('#b85138'),green=mat('#7e9660'),pink=mat('#e2a3ad'),dark=mat('#34332b');
 function part(g,geo,m,p,s){const o=new T.Mesh(geo,m);o.position.set(...p);o.scale.set(...s);g.add(o);return o}const box=(g,m,p,s)=>part(g,cube,m,p,s),ball=(g,m,p,s)=>part(g,sphere,m,p,s);
 function tube(g,m,points,r=.009){const geo=new T.TubeGeometry(new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p))),10,r,5,false);return part(g,geo,m,[0,0,0],[1,1,1])}
 function product(id){if(!['tofu','figurine','dango','takoyaki','taiyaki'].includes(id))return null;const g=new T.Group();
  if(id==='tofu'){box(g,M.wood,[0,.03,0],[.48,.055,.38]);for(const z of[-.20,.20])box(g,M.wood,[0,.09,z],[.50,.10,.025]);for(const x of[-.25,.25])box(g,M.wood,[x,.09,0],[.025,.10,.40]);for(const x of[-.11,.11])for(const z of[-.085,.085])box(g,mat('#f5efdf'),[x,.10,z],[.19,.13,.14]);const leaf=ball(g,green,[.09,.175,0],[.09,.006,.045]);leaf.rotation.y=-.4;box(g,cream,[-.12,.18,-.02],[.13,.006,.16]);tube(g,brown,[[-.14,.185,-.075],[-.11,.185,-.02],[-.14,.185,.04]],.003)}
  if(id==='dango'){part(g,rod,M.wood,[0,.22,0],[.009,.58,.009]);for(const[y,m]of[[.12,green],[.27,white],[.42,pink]]){ball(g,m,[0,y,0],[.084,.077,.082]);ball(g,mat('#fff3d9'),[-.025,y+.025,.065],[.022,.006,.004])}}
  if(id==='takoyaki'){box(g,cream,[0,.025,0],[.56,.04,.45]);for(const z of[-.225,.225]){const wall=box(g,cream,[0,.085,z],[.57,.12,.018]);wall.rotation.x=Math.sign(z)*-.18}for(const x of[-.28,.28]){const wall=box(g,cream,[x,.085,0],[.018,.12,.46]);wall.rotation.z=Math.sign(x)*.2}for(const x of[-.12,.12])for(const z of[-.1,.1]){ball(g,baked,[x,.12,z],[.10,.09,.095]);tube(g,brown,[[x-.065,.185,z-.025],[x,.205,z],[x+.065,.18,z+.025]],.012);tube(g,white,[[x-.055,.19,z+.025],[x,.21,z+.01],[x+.05,.19,z-.025]],.006);for(let i=0;i<4;i++){const leaf=box(g,green,[x+Math.sin(i*4)*.05,.207,z+Math.cos(i*3)*.04],[.022,.003,.008]);leaf.rotation.y=i}}}
  if(id==='taiyaki'){const s=new T.Shape();s.moveTo(-.18,.12);s.quadraticCurveTo(-.30,.3,-.13,.42);s.quadraticCurveTo(.07,.52,.17,.36);s.lineTo(.29,.43);s.lineTo(.25,.27);s.lineTo(.3,.17);s.lineTo(.13,.20);s.quadraticCurveTo(-.05,.03,-.18,.12);s.closePath();const geo=new T.ExtrudeGeometry(s,{depth:.06,bevelEnabled:true,bevelSize:.025,bevelThickness:.02,bevelSegments:3,curveSegments:12,steps:1});part(g,geo,baked,[0,0,0],[1,1,1]);ball(g,brown,[-.16,.33,.09],[.015,.015,.007]);tube(g,brown,[[-.13,.25,.09],[-.09,.31,.096],[-.1,.39,.088]],.007);for(let row=0;row<3;row++)for(let col=0;col<3;col++){const x=-.055+col*.055,y=.20+row*.055;tube(g,mat('#a9733d'),[[x-.02,y,.091],[x,y+.012,.096],[x+.02,y,.091]],.0035)}tube(g,brown,[[.17,.29,.09],[.25,.34,.087]],.004)}
  if(id==='figurine'){box(g,M.wood,[0,.026,0],[.38,.05,.34]);ball(g,white,[0,.19,0],[.115,.18,.10]);ball(g,white,[0,.41,.01],[.13,.11,.11]);for(const x of[-.09,.09]){part(g,cone,white,[x,.52,.0],[.055,.12,.04]);part(g,cone,pink,[x,.525,.033],[.03,.07,.008]);ball(g,white,[x*.7,.08,.09],[.044,.055,.06]);ball(g,dark,[x*.63,.42,.108],[.008,.012,.004])}ball(g,white,[0,.38,.12],[.075,.04,.055]);ball(g,dark,[0,.39,.17],[.019,.014,.012]);const bib=box(g,red,[0,.30,.103],[.13,.12,.014]);bib.rotation.x=.14;tube(g,white,[[.07,.07,-.04],[.21,.12,-.08],[.21,.32,-.08],[.12,.39,-.06]],.044);ball(g,mat('#f9f4e8',.3),[.12,.39,-.06],[.045,.055,.04])}
  return g;
 }
 return{product};
}
